"""Bounded exact fiber enumeration, allowing irreducible multi-row trades."""
import hashlib,itertools,json,random,sys
from collections import Counter,defaultdict,deque
from pathlib import Path
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT.parent/'edge-row-ordinal'))
import analyze as base
from vs import corpus,dsl,ivtff
FACT=base.FACT
PLAN={
 'question':'Do trades requiring3+rows add layouts beyond the known two-row component while preserving all margins?',
 'blocks':'All P rows in the same public page and same original token-count width n, as in previous diagnostics.',
 'constraints':'Each original row word multiset; each (page,n,exact original k) word multiset; exact EVA-basic length at each literal slot; uncertainty/empty barriers frozen. No physical x-coordinate interpretation.',
 'method':'Complete constraint search of assignments in each block, using row/column counts, positional length domains, forced placements and deterministic minimum-domain branching. Allows simultaneous trades involving any number of rows. Exact completeness is reported per block.',
 'limits':{'nodes_per_block':250000,'solutions_per_block':4096,'stored_solutions_per_edition':20000},
 'two_row_comparison':'Regenerate the exact observed component under all balanced two-row moves per block. A feasible layout outside that component is a witness that two-row moves alone cannot reach it.',
 'sample':'Same34public practice evaluation pages, ZL and IT; not fresh independent pages.',
 'decision':'A confirmatory-style public diagnostic is reported only if EVERY block enumeration is complete, >=100 distinct global layouts and >=30 movable adjacent pairs, with a nonconstant null. Otherwise report incomplete or insufficient, never relax constraints after outcomes.',
 'null_if_testable':'199exact uniform independent product-of-block draws, integer solution index, seed408, one-sided plus-one p<=.01 required in both editions. No MCMC mixing claim.',
 'scope':'No search on heldout pages. Full fiber only within page/equal-width blocks. New unconstrained generators are not tuned to this result. No language claim from a pass.',
 'fact_sha256':hashlib.sha256(FACT.read_bytes()).hexdigest()}

class Limit(Exception):pass

def enumerate_block(rows):
    nr=len(rows);n=len(rows[0]);original=tuple(w for row in rows for w in row)
    cells=[i for i,w in enumerate(original) if base.eligible(w)]
    targets_r=[Counter(w for w in row if base.eligible(w)) for row in rows]
    targets_c=[Counter(rows[r][k] for r in range(nr) if base.eligible(rows[r][k])) for k in range(n)]
    lengths=[len(dsl.SEG(w)) for w in original]
    candidates={i:sorted(w for w in targets_r[i//n] if w in targets_c[i%n] and len(dsl.SEG(w))==lengths[i]) for i in cells}
    start=[None if i in candidates else w for i,w in enumerate(original)]
    solutions=[];nodes=0;complete=True
    def visit(assignment):
        nonlocal nodes
        nodes+=1
        if nodes>250000:raise Limit('node limit')
        remaining_r=[c.copy() for c in targets_r];remaining_c=[c.copy() for c in targets_c]
        for i in cells:
            w=assignment[i]
            if w is not None:remaining_r[i//n][w]-=1;remaining_c[i%n][w]-=1
        while True:
            domains={i:[w for w in candidates[i] if remaining_r[i//n][w]>0 and remaining_c[i%n][w]>0] for i in cells if assignment[i] is None}
            if any(not d for d in domains.values()):return
            if not domains:
                assert all(not any(c.values()) for c in remaining_r+remaining_c)
                if len(solutions)>=4096:raise Limit('solution limit')
                solutions.append(tuple(assignment));return
            forced={i:d[0] for i,d in domains.items() if len(d)==1}
            for axis,remaining in [('r',remaining_r),('c',remaining_c)]:
                available=defaultdict(list)
                for i,domain in domains.items():
                    for w in domain:available[(i//n if axis=='r' else i%n,w)].append(i)
                for j,counter in enumerate(remaining):
                    for w,count in counter.items():
                        if count<=0:continue
                        places=available[j,w]
                        if len(places)<count:return
                        if len(places)==count:
                            for i in places:
                                if i in forced and forced[i]!=w:return
                                forced[i]=w
            if not forced:break
            for i,w in forced.items():
                assignment[i]=w;remaining_r[i//n][w]-=1;remaining_c[i%n][w]-=1
                if remaining_r[i//n][w]<0 or remaining_c[i%n][w]<0:return
        i=min(domains,key=lambda x:(len(domains[x]),x))
        for w in domains[i]:
            child=list(assignment);child[i]=w;visit(child)
    reason=None
    try:visit(start)
    except Limit as exc:complete=False;reason=str(exc)
    if complete:assert original in solutions
    return {'layouts':solutions,'complete':complete,'reason':reason,'nodes':nodes}

def check_layout(original,target,n):
    nr=len(original)//n
    assert all(len(dsl.SEG(a))==len(dsl.SEG(b)) for a,b in zip(original,target))
    assert all(a==b for a,b in zip(original,target) if not base.eligible(a))
    for r in range(nr):assert Counter(original[r*n:(r+1)*n])==Counter(target[r*n:(r+1)*n])
    for k in range(n):assert Counter(original[k::n])==Counter(target[k::n])

def two_row_component(rows):
    n=len(rows[0]);nr=len(rows);first=tuple(w for row in rows for w in row);seen={first};queue=deque([first])
    while queue:
        state=queue.popleft()
        for a,b in itertools.combinations(range(nr),2):
            m=base.Pair(list(state[a*n:(a+1)*n]),list(state[b*n:(b+1)*n]))
            if m.states>4096:return seen,False
            for rank in range(m.states):
                x,y=m.assignment(rank);target=list(state);target[a*n:(a+1)*n]=x;target[b*n:(b+1)*n]=y;target=tuple(target)
                if target not in seen:
                    if len(seen)>=4096:return seen,False
                    check_layout(first,target,n);seen.add(target);queue.append(target)
    return seen,True

def selfcheck():
    # Latin3 has a smaller two-row component than its full twelve-layout fiber.
    rows=[['aa','rr','xx'],['xx','aa','rr'],['rr','xx','aa']]
    e=enumerate_block(rows);n=3
    brute=[]
    for cols in itertools.product(*(set(itertools.permutations([row[k] for row in rows])) for k in range(n))):
        candidate=tuple(cols[k][r] for r in range(3) for k in range(n))
        if all(Counter(candidate[r*n:(r+1)*n])==Counter(rows[r]) for r in range(3)):brute.append(candidate)
    assert e['complete'] and set(e['layouts'])==set(brute)
    for target in e['layouts']:check_layout(tuple(w for r in rows for w in r),target,n)
    # Independent Latin3x3 oracle: exactly12 matrices with each symbol once per row/column.
    assert len(e['layouts'])==12
    pair,complete=two_row_component(rows)
    assert complete and len(pair)<len(e['layouts'])
    barriers=[['?','aa','rr'],['?','rr','aa']]
    e2=enumerate_block(barriers);assert e2['complete'] and len(e2['layouts'])==2
    for target in e2['layouts']:check_layout(tuple(w for r in barriers for w in r),target,3)
    inert=enumerate_block([['a','rr'],['rr','a']]);assert inert['complete'] and len(inert['layouts'])==1
    return {'latin3_full_layouts':12,'latin3_two_row_component':len(pair),'brute_force_matches':True,'barriers_and_lengths_pass':True}

def run(pages):
    ts=dsl.tokens(pages);rows=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']=='P':rows[t['line']].append(i)
    blocks=defaultdict(list)
    for row in rows.values():
        row.sort(key=lambda i:ts[i]['k']);assert [ts[i]['k'] for i in row]==list(range(ts[row[0]]['n']))
        blocks[(ts[row[0]]['page'],ts[row[0]]['n'])].append(row)
    reports=[];models=[];stored=0;full=True;support=1;two_support=1;mobile=set();witnesses=[]
    for key,rs in sorted(blocks.items()):
        words=[[ts[i]['w'] for i in row] for row in rs];original=tuple(w for row in words for w in row);n=key[1]
        e=enumerate_block(words);stored+=len(e['layouts'])
        if stored>20000:e['complete']=False;e['reason']='edition storage limit';full=False
        pair,pair_complete=two_row_component(words)
        if not pair_complete:full=False
        for layout in e['layouts']:check_layout(original,layout,n)
        new=[layout for layout in e['layouts'] if layout not in pair] if pair_complete else []
        report={'page':ts[rs[0][0]]['folio'],'n':n,'rows':[ts[row[0]]['lid'] for row in rs],
                'full_count_or_lower_bound':len(e['layouts']),'complete':e['complete'],'nodes':e['nodes'],'reason':e['reason'],
                'two_row_count':len(pair),'two_row_complete':pair_complete,'outside_two_row_component':len(new)}
        if new:
            layout=new[0];changes=[{'row':ts[rs[j//n][0]]['lid'],'k':j%n,'old':original[j],'new':w} for j,w in enumerate(layout) if w!=original[j]]
            witnesses.append({'page':report['page'],'n':n,'changes':changes,'changed_rows':len({c['row'] for c in changes})})
            assert witnesses[-1]['changed_rows']>=3
        reports.append(report)
        if not e['complete']:full=False
        support*=len(e['layouts']);two_support*=len(pair)
        for j,w in enumerate(original):
            if any(layout[j]!=w for layout in e['layouts']):
                i=rs[j//n][j%n];mobile.add((ts[i]['line'],ts[i]['k']))
        models.append((rs,e['layouts']))
        if stored>20000:break
    sel={'unit':['P'],'certain':True};st={'edge_length_cmi':True}
    chosen=dsl.select(ts,sel);adj=dsl._edge_length_pairs(chosen);obs=dsl.statistic(st,chosen,ts)
    affected=sum((a['line'],a['k']) in mobile or (b['line'],b['k']) in mobile for a,b in adj)
    adequate=full and support>=100 and affected>=30
    values=[];p=None
    if adequate:
        rng=random.Random(408)
        for _ in range(199):
            words=[t['w'] for t in ts]
            for rs,layouts in models:
                layout=layouts[rng.randrange(len(layouts))];n=len(rs[0])
                for r,row in enumerate(rs):
                    for k,i in enumerate(row):words[i]=layout[r*n+k]
            sh=[dict(t,w=w) for t,w in zip(ts,words)]
            values.append(dsl.statistic(st,dsl.select(sh,sel),sh))
        if any(abs(v-obs)>1e-12 for v in values):p=(1+sum(v>=obs for v in values))/200
    return {'complete_full_fiber':full,'distinct_layouts_or_lower_bound':str(support),'two_row_component_layouts':str(two_support),
            'stored_block_layouts':stored,'changing_word_positions':len(mobile),'affected_adjacent_pairs':affected,'adjacent_pairs':len(adj),
            'observed_bits':obs,'adequate':adequate and p is not None,'p':p,'passes':p is not None and p<=.01,
            'block_reports':reports,'irreducible_multirow_witnesses':witnesses,'permutation_values':values}

if __name__=='__main__':
    if '--plan' in sys.argv:
        ROOT.mkdir(exist_ok=True);(ROOT/'plan.json').write_text(json.dumps(PLAN,indent=2)+'\n',encoding='utf-8');print('Plan frozen');sys.exit()
    assert json.loads((ROOT/'plan.json').read_text())==PLAN
    report={'plan':PLAN,'selfcheck':selfcheck(),'results':{}}
    for ed in ('zl','it'):
        _,ev=corpus.split_pages('practice',ed);report['results'][ed]=run(ev)
        print(ed,{k:v for k,v in report['results'][ed].items() if k not in ('block_reports','permutation_values','irreducible_multirow_witnesses')},flush=True)
        print('witnesses',report['results'][ed]['irreducible_multirow_witnesses'][:3],flush=True)
        (ROOT/'results.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
    assert hashlib.sha256(FACT.read_bytes()).hexdigest()==PLAN['fact_sha256'];report['fact_unchanged']=True
    (ROOT/'results.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')

