"""Independent row-permutation oracle for the cell-constraint search."""
import hashlib,itertools,json,random
from collections import Counter,defaultdict
from pathlib import Path
import run as primary
ROOT=Path(__file__).resolve().parent

def oracle(rows):
    nr=len(rows);n=len(rows[0]);columns=[Counter(rows[r][k] for r in range(nr)) for k in range(n)]
    options=[]
    for row in rows:
        target=Counter(row);possibilities=[]
        def permute(k,partial):
            if k==n:possibilities.append(tuple(partial));return
            if not primary.base.eligible(row[k]):candidates=[row[k]]
            else:candidates=sorted(w for w in target if primary.base.eligible(w) and len(primary.dsl.SEG(w))==len(primary.dsl.SEG(row[k])) and columns[k][w])
            for w in candidates:
                if target[w]>0:
                    target[w]-=1;permute(k+1,partial+[w]);target[w]+=1
        permute(0,[]);assert tuple(row) in possibilities
        options.append(possibilities)
    ordering=sorted(range(nr),key=lambda r:(len(options[r]),r));assignments=[None]*nr;result=[]
    remaining=[c.copy() for c in columns]
    def join(j):
        if j==nr:result.append(tuple(w for row in assignments for w in row));return
        r=ordering[j]
        for row in options[r]:
            if not all(remaining[k][w]>0 for k,w in enumerate(row)):continue
            assignments[r]=row
            for k,w in enumerate(row):remaining[k][w]-=1
            join(j+1)
            for k,w in enumerate(row):remaining[k][w]+=1
    join(0)
    return set(result)

def fixtures():
    rng=random.Random(912)
    for i in range(60):
        rows=[[rng.choice(['a','r','aa','rr','?','']) for k in range(3)] for r in range(3)]
        first=primary.enumerate_block(rows);assert first['complete']
        second=oracle(rows);assert set(first['layouts'])==second,(i,rows)
    rows=[['aa','rr','xx'],['xx','aa','rr'],['rr','xx','aa']]
    assert len(oracle(rows))==12
    return {'random_tiny_cases':60,'all_primary_vs_oracle_match':True,'independent_latin3_count':12}

def check(pages):
    ts=primary.dsl.tokens(pages);row_indices=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']=='P':row_indices[t['line']].append(i)
    blocks=defaultdict(list)
    for row in row_indices.values():
        row.sort(key=lambda i:ts[i]['k']);blocks[(ts[row[0]]['page'],ts[row[0]]['n'])].append(row)
    support=1;comparisons=[]
    for key,rs in sorted(blocks.items()):
        rows=[[ts[i]['w'] for i in row] for row in rs]
        first=primary.enumerate_block(rows);assert first['complete']
        second=oracle(rows);assert set(first['layouts'])==second,(key,len(first['layouts']),len(second))
        support*=len(second);comparisons.append({'page':ts[rs[0][0]]['folio'],'n':key[1],'count':len(second),'row_count':len(rs)})
    return {'all_block_layout_sets_match':True,'block_count':len(blocks),'global_layout_count':str(support),'blocks':comparisons}

if __name__=='__main__':
    result={'method':'Independent per-row permutation enumeration plus column-count join; post-primary correctness check, not a new hypothesis test.',
            'fixtures':fixtures(),'results':{}}
    for edition in ('zl','it'):
        _,pages=primary.corpus.split_pages('practice',edition);result['results'][edition]=check(pages)
        print(edition,{k:v for k,v in result['results'][edition].items() if k!='blocks'},flush=True)
    (ROOT/'verification.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8')
    paths=[ROOT/'plan.json',ROOT/'run.py',ROOT/'verify.py',ROOT.parent/'edge-row-ordinal/analyze.py',ROOT.parent/'edge-cmi-current/vs/dsl.py']
    (ROOT/'reproduction-hashes.json').write_text(json.dumps({str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},indent=2)+'\n',encoding='utf-8')

