"""Exact conditional sampler preserving row inventories and column word marginals."""
import hashlib,json,random,sys
from collections import Counter,defaultdict
from functools import lru_cache
from pathlib import Path
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT.parent/'edge-cmi-current'))
import vs
vs.ROOT=str(ROOT.parent/'voynich-swarm')
from vs import corpus,dsl,generators,ivtff
FACT=ROOT.parent/'edge-cmi-preparation/staged/experiments/P-L2-020/Pavlenko77/fact.json'
PLAN={
 'question':'Can exact ordinal/length word marginals and each original line word multiset be preserved simultaneously while testing edge association?',
 'sample':'Same34 public practice evaluation pages, ZL and IT; previously used pages.',
 'pairing':'Within each page and original token-count width n, greedily pair unused P rows by decreasing overlap of their certain-word multisets; tie by original row order. Pairing reads only invariant row inventories, never word order or edge statistics.',
 'conditioning':'In each fixed row pair, keep the unordered pair of words at every original index k fixed. Only columns with two certain nonempty words of equal EVA-basic length may change. Keep the word multiset of each original row exactly fixed. Other rows and columns remain frozen.',
 'sampler':'Dynamic programming counts every feasible assignment to row A under its fixed multiset; row B gets the other word at each column. Sample exactly uniformly using integer completion counts. Disjoint row-pair choices are independent; no MCMC or mixing assumption. Two-word exchanges and longer balanced cycles both allowed.',
 'scope':'A conditional orbit for fixed row pairs, not the entire fiber of all possible multi-row trades. Row-pair column marginals are stronger constraints than page-wide ordinal marginals.',
 'metric':'Unchanged edge_length_cmi in certain literal adjacent P words; gaps and line boundaries stay barriers.',
 'replicates':199,'seed':408,'alpha':.01,'min_movable_pairs':30,'min_distinct_layouts':100,
 'decision':'Support only if both editions have >=30 potentially movable adjacent pairs, >=100 distinct conditional layouts, a nonconstant null, and one-sided plus-one p<=.01. Otherwise report insufficient or invariant, never relax constraints after results.',
 'cost_limit':'At most250000 dynamic-programming states per row pair; exceeding it makes this diagnostic undefined rather than changing the sampler.',
 'controls':[{'generator':'G-line-chain','seed':4,'order':4},{'generator':'unigram','seed':221}],
 'limits':'Exact transcription index k and token-count width n; no physical x coordinates or spacing. One seed per generator. A non-rejection is not proof that positions explain the association.',
 'fact_sha256':hashlib.sha256(FACT.read_bytes()).hexdigest()}

def eligible(w):return bool(dsl.SEG(w)) and not ivtff.uncertain(w)

class Pair:
    def __init__(self,a,b):
        self.a=a;self.b=b
        self.cols=[i for i,(x,y) in enumerate(zip(a,b)) if eligible(x) and eligible(y) and x!=y and len(dsl.SEG(x))==len(dsl.SEG(y))]
        self.words=sorted({a[i] for i in self.cols}|{b[i] for i in self.cols})
        indices={w:i for i,w in enumerate(self.words)}
        self.options=[(indices[a[i]],indices[b[i]]) for i in self.cols]
        counts=Counter(a[i] for i in self.cols)
        self.initial=tuple(counts[w] for w in self.words)
        self.calls=0
        @lru_cache(None)
        def count(j,remaining):
            self.calls+=1
            if self.calls>250000:raise RuntimeError('DP state limit reached')
            if j==len(self.cols):return int(not any(remaining))
            total=0
            for x in self.options[j]:
                if remaining[x]:
                    nxt=list(remaining);nxt[x]-=1
                    total+=count(j+1,tuple(nxt))
            return total
        self.count=count;self.states=count(0,self.initial)
        assert self.states>=1
        # A column can flip iff its directed word edge belongs to a directed cycle.
        graph=defaultdict(set)
        for i in self.cols:graph[a[i]].add(b[i])
        def reaches(start,target):
            todo=[start];seen=set()
            while todo:
                x=todo.pop()
                if x==target:return True
                if x not in seen:seen.add(x);todo.extend(graph[x])
            return False
        self.movable=[i for i in self.cols if reaches(b[i],a[i])]

    def assignment(self,rank):
        assert 0<=rank<self.states
        a=list(self.a);b=list(self.b);remaining=self.initial
        for j,col in enumerate(self.cols):
            for x in self.options[j]:
                if not remaining[x]:continue
                nxt=list(remaining);nxt[x]-=1;nxt=tuple(nxt)
                count=self.count(j+1,nxt)
                if rank>=count:rank-=count;continue
                w=self.words[x];a[col]=w;b[col]=self.b[col] if w==self.a[col] else self.a[col]
                remaining=nxt;break
            else:raise AssertionError('no feasible completion')
        assert not any(remaining)
        return a,b

def build(ts):
    rows=defaultdict(list)
    for i,t in enumerate(ts):
        if t['unit']=='P':rows[t['line']].append(i)
    blocks=defaultdict(list)
    for row in rows.values():
        row.sort(key=lambda i:ts[i]['k'])
        assert [ts[i]['k'] for i in row]==list(range(ts[row[0]]['n']))
        blocks[(ts[row[0]]['page'],ts[row[0]]['n'])].append(row)
    pairs=[];metadata=[]
    for key,block in sorted(blocks.items()):
        inv=[Counter(ts[i]['w'] for i in row if eligible(ts[i]['w'])) for row in block]
        candidates=sorted(((-sum((inv[a]&inv[b]).values()),a,b) for a in range(len(block)) for b in range(a+1,len(block))))
        used=set()
        for score,a,b in candidates:
            if a in used or b in used:continue
            used.update((a,b));ra,rb=block[a],block[b]
            model=Pair([ts[i]['w'] for i in ra],[ts[i]['w'] for i in rb])
            pairs.append((ra,rb,model));metadata.append({'page':ts[ra[0]]['folio'],'n':key[1],'rows':[ts[ra[0]]['lid'],ts[rb[0]]['lid']],'inventory_overlap':-score,'states':model.states,'movable_columns':model.movable,'dp_states':model.calls})
    return pairs,metadata

def invariants(ts,sh,pairs):
    for a,b in zip(ts,sh):
        assert {k:v for k,v in a.items() if k!='w'}=={k:v for k,v in b.items() if k!='w'}
        assert len(dsl.SEG(a['w']))==len(dsl.SEG(b['w']))
        if a['unit']!='P' or not eligible(a['w']):assert a['w']==b['w']
    for a,b in zip(dsl.lines_of(ts),dsl.lines_of(sh)):
        assert Counter(t['w'] for t in a)==Counter(t['w'] for t in b)
    def column_inventory(tokens):return Counter((t['page'],t['n'],t['k'],t['w']) for t in tokens)
    assert column_inventory(ts)==column_inventory(sh)
    for ra,rb,_ in pairs:
        for i,j in zip(ra,rb):assert Counter([ts[i]['w'],ts[j]['w']])==Counter([sh[i]['w'],sh[j]['w']])

def run(pages):
    ts=dsl.tokens(pages);sel={'unit':['P'],'certain':True};st={'edge_length_cmi':True}
    chosen=dsl.select(ts,sel);obs=dsl.statistic(st,chosen,ts);adj=dsl._edge_length_pairs(chosen)
    pairs,meta=build(ts);support=1;spots=set()
    for ra,rb,m in pairs:
        support*=m.states
        for k in m.movable:
            for i in (ra[k],rb[k]):spots.add((ts[i]['line'],ts[i]['k']))
    movable=sum((a['line'],a['k']) in spots or (b['line'],b['k']) in spots for a,b in adj)
    rng=random.Random(408);values=[];invariant_checks=0
    # Report the null descriptively even if the frozen support/mobility gate fails.
    for draw in range(199):
        words=[t['w'] for t in ts]
        for ra,rb,m in pairs:
            a,b=m.assignment(rng.randrange(m.states))
            for i,w in zip(ra,a):words[i]=w
            for i,w in zip(rb,b):words[i]=w
        sh=[dict(t,w=w) for t,w in zip(ts,words)]
        invariants(ts,sh,pairs);invariant_checks+=1
        values.append(dsl.statistic(st,dsl.select(sh,sel),sh))
    nonconstant=any(abs(v-obs)>1e-12 for v in values)
    adequate=movable>=30 and support>=100 and nonconstant
    p=(1+sum(v>=obs for v in values))/200
    return {'pages':len(pages),'observed_bits':obs,'adjacent_pairs':len(adj),'movable_pairs':movable,'movable_pair_share':movable/len(adj),
            'distinct_layouts':str(support),'row_pairs':len(pairs),'active_row_pairs':sum(m.states>1 for _,_,m in pairs),
            'nonconstant':nonconstant,'adequate':adequate,'status':'testable under frozen gates' if adequate else 'insufficient conditional mobility/support',
            'p':p if adequate else None,'descriptive_mc_tail':p,'passes':adequate and p<=.01,
            'null_mean':sum(values)/199,'null_min':min(values),'null_max':max(values),'excess':obs-sum(values)/199,
            'invariant_checks':invariant_checks,'pair_models':meta,'permutation_values':values}

def selfcheck():
    import itertools
    for a,b,expected in [(['aa','rr'],['rr','aa'],2),(['aa','rr','oo'],['rr','oo','aa'],2),
                          (['aa','aa','rr','rr'],['rr','rr','aa','aa'],6),(['a','rr'],['rr','a'],1)]:
        m=Pair(a,b);assert m.states==expected
        brute=set()
        for bits in itertools.product((0,1),repeat=len(m.cols)):
            x=list(a);y=list(b)
            for bit,col in zip(bits,m.cols):
                if bit:x[col],y[col]=y[col],x[col]
            if Counter(x)==Counter(a) and Counter(y)==Counter(b):brute.add((tuple(x),tuple(y)))
        got={tuple(map(tuple,m.assignment(rank))) for rank in range(m.states)};assert got==brute
        mobile={i for x,y in brute for i in range(len(a)) if x[i]!=a[i]}
        assert mobile==set(m.movable)
    return 'Exact counts, all ranked assignments and movable columns match brute-force enumeration: rectangle, three-cycle, repeated-word six-state case, unequal-length inert case.'

